    correction: [{"quoi":"نترجم","math":"المسافة تقسم 264 و 154، إذن هي قاسم مشترك لهما"},{"quoi":"نفكّك إلى عوامل أوّلية","math":"<span dir=\"ltr\" class=\"expr\">264 = 2<sup>3</sup> × 3 × 11</span> و <span dir=\"ltr\" class=\"expr\">154 = 2 × 7 × 11</span>"},{"quoi":"ق.م.أ","math":"<span dir=\"ltr\" class=\"expr\">2 × 11 = 22</span>"},{"quoi":"القيم الممكنة = قواسم 22","math":"{ 1 ; 2 ; 11 ; 22 } بالمتر"},{"quoi":"المحصورة بين 20 و 30","math":"<span dir=\"ltr\" class=\"expr\">= 22</span> متر"},{"quoi":"نحسب المحيط","math":"<span dir=\"ltr\" class=\"expr\">2 × (264 + 154) = 836</span>"},{"quoi":"عدد الأشجار","math":"<span dir=\"ltr\" class=\"expr\">836 : 22 = 38</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">= 38</span>"}],
